        int best=0; string bs=s.substr(i,1);
        for(int r=1;r<=R;r++){string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;best=r;}}
        b[i]=best;
    }
    return b;
}
vi h1All(const string&s){
    int n=s.size(); vi h(n);
    for(int i=0;i<n;i++){
        int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
        char m='z'+1; for(int t=0;t<=R;t++)m=min(m,s[i-t]);
