#include <bits/stdc++.h>
using namespace std;
typedef vector<int> vi;
vi bruteAll(const string&s){
    int n=s.size(); vi b(n);
    for(int i=0;i<n;i++){
        int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
        int best=0; string bs=s.substr(i,1);
        for(int r=1;r<=R;r++){string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;best=r;}}
        b[i]=best;
    }
    return b;
}
int lcp(const string&s,int a,int b){int n=s.size();int l=0;while(a+l<n&&b+l<n&&s[a+l]==s[b+l])l++;return l;}
vi formAll(const string&s){
    int n=s.size(); vi ans(n);
    for(int i=0;i<n;i++){
        int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
        int L=i-R;
        int ps=L;
        for(int p=L;p<=i;p++){
            if(p==L) continue;
            // compare suffix p vs suffix ps
            if(s.compare(p,string::npos,s,ps,string::npos)<0) ps=p;
        }
        int bestp=ps;
        for(int q=i;q>=ps;q--){
            int Lq=2*(i-q)+1;
            if(lcp(s,ps,q)>=Lq){bestp=q;break;}
        }
        ans[i]=i-bestp;
    }
    return ans;
}
