#include <bits/stdc++.h>
using namespace std;
int lcp(const string&s,int a,int b){int n=s.size();int l=0;while(a+l<n&&b+l<n&&s[a+l]==s[b+l])l++;return l;}
long long bad=0; string ex="";
void check(const string&s){
    int n=s.size();
    for(int i=0;i<n;i++){
        int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
        int L=i-R;
        int ps=L;
        for(int p=L+1;p<=i;p++) if(s.compare(p,string::npos,s,ps,string::npos)<0) ps=p;
        int tstar=i-ps;
        int Wlen=2*tstar+1;
        string W=s.substr(ps,Wlen);
        // max valid d
        int maxvalid=0;
        for(int d=1;d<=tstar;d++) if(lcp(s,ps,ps+d)>=Wlen-2*d) maxvalid=d;
        // max full period <= tstar
        int maxper=0;
        for(int d=1;d<=tstar;d++){
            bool ok=true;
            for(int u=0;u+d<Wlen;u++) if(W[u]!=W[u+d]){ok=false;break;}
            if(ok) maxper=d;
        }
        if(maxvalid!=maxper){ bad++; if(ex.empty())ex=s; return; }
    }
}
int main(){
    for(int n=1;n<=14;n++) for(int mask=0;mask<(1<<n);mask++){
        string s(n,'a'); for(int j=0;j<n;j++) if(mask>>j&1) s[j]='b'; check(s);
    }
    for(int n=1;n<=8;n++){ long long tot=1; for(int j=0;j<n;j++)tot*=3;
        for(long long mask=0;mask<tot;mask++){ string s(n,'a'); long long x=mask; for(int j=0;j<n;j++){s[j]='a'+x%3;x/=3;} check(s);} }
    mt19937 rng(123);
    for(int it=0;it<20000;it++){ int n=1+rng()%16; int a=4+rng()%4; string s(n,'a'); for(char&c:s)c='a'+rng()%a; check(s); }
    cout<<"bad="<<bad<<" ex="<<ex<<"\n";
}

