#include <bits/stdc++.h>
using namespace std;
int main(){
    int bestSum=0,bestSumT=0; string bs,bsT;
    for(int n=1;n<=15;n++){
        for(int mask=0;mask<(1<<n);mask++){
            string s(n,'a'); for(int j=0;j<n;j++) if(mask>>j&1) s[j]='b';
            int sumA=0,sumT=0;
            for(int i=0;i<n;i++){
                int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
                int best=0; string bests=s.substr(i,1);
                for(int r=1;r<=R;r++){string t=s.substr(i-r,2*r+1); if(t<bests){bests=t;best=r;}}
                sumA+=best;
                // p* min suffix rank
                int L=i-R,ps=L;
                for(int p=L+1;p<=i;p++) if(s.compare(p,string::npos,s,ps,string::npos)<0) ps=p;
                sumT += i-ps;
            }
            if(sumA>bestSum){bestSum=sumA;bs=s;}
            if(sumT>bestSumT){bestSumT=sumT;bsT=s;}
        }
    }
    cout<<"maxSumAns="<<bestSum<<" s="<<bs<<"\n";
    cout<<"maxSumT="<<bestSumT<<" s="<<bsT<<"\n";
}

