#include <bits/stdc++.h>
using namespace std;
const int MAXN=200005;
int nxt[MAXN][26], len_[MAXN], link_[MAXN], par_[MAXN], st_[MAXN];
int cnt, last_;
string s; int n;
vector<int> lastNode;

void buildEertree(){
    memset(nxt,-1,sizeof(nxt));
    len_[0]=-1; link_[0]=0;
    len_[1]=0; link_[1]=0;
    cnt=2; last_=1; st_[0]=st_[1]=-1;
    lastNode.assign(n,0);
    for(int pos=0;pos<n;pos++){
        int c=s[pos]-'a';
        int cur=last_;
        while(true){ int cl=len_[cur]; if(pos-1-cl>=0 && s[pos-1-cl]==s[pos]) break; cur=link_[cur]; }
        if(nxt[cur][c]!=-1){ last_=nxt[cur][c]; lastNode[pos]=last_; continue; }
        int v=cnt++;
        len_[v]=len_[cur]+2; st_[v]=pos-len_[v]+1; par_[v]=cur; nxt[cur][c]=v;
        if(len_[v]==1) link_[v]=1;
        else { int t=link_[cur]; while(true){ int tl=len_[t]; if(pos-1-tl>=0 && s[pos-1-tl]==s[pos]) break; t=link_[t]; } link_[v]=nxt[t][c]; }
        last_=v; lastNode[pos]=last_;
    }
}
int cmpNode(int a,int b){
    return s.compare(st_[a], len_[a], s, st_[b], len_[b]);
}
int main(){
    mt19937 rng(2024);
    for(int iter=0;iter<30000;iter++){
        n=1+rng()%12;
        s.assign(n,'a'); for(char&c:s)c='a'+rng()%3;
        // brute
        vector<int> brute(n);
        for(int i=0;i<n;i++){
            int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
            int best=0; string bs=s.substr(i,1);
            for(int r=1;r<=R;r++){string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;best=r;}}
            brute[i]=best;
        }
        // eertree
        buildEertree();
        vector<int> best(cnt);
        vector<int> ord(cnt-2);
        for(int i=0;i<cnt-2;i++) ord[i]=i+2;
        sort(ord.begin(),ord.end(),[](int a,int b){return len_[a]<len_[b];});
        for(int v:ord){
            int p=par_[v];
            if(p<=1) best[v]=v;
            else best[v]=(cmpNode(v,best[p])<0)?v:best[p];
        }
        // manacher odd
        vector<int> d1(n);
        for(int i=0,l=0,r=-1;i<n;i++){
            int k=(i>r)?1:min(d1[l+r-i],r-i+1);
            while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++;
            d1[i]=k-1;
            if(i+k-1>r){l=i-k+1;r=i+k-1;}
        }
        vector<int> ans(n);
        for(int i=0;i<n;i++){
            int L=2*d1[i]+1; int e=i+d1[i];
            int v=lastNode[e];
            while(len_[v]>L) v=link_[v];
            if(len_[v]!=L){ cout<<"FAIL node lookup s="<<s<<" i="<<i<<" L="<<L<<" got="<<len_[v]<<"\n"; return 0; }
            ans[i]=(len_[best[v]]-1)/2;
        }
        if(ans!=brute){
            cout<<"MISMATCH s="<<s<<"\n brute:"; for(int x:brute)cout<<' '<<x; cout<<"\n eert:"; for(int x:ans)cout<<' '<<x; cout<<"\n";
            return 0;
        }
    }
    cout<<"ALL OK\n";
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN=64;
int nxt[MAXN][26], len_[MAXN], link_[MAXN], par_[MAXN], st_[MAXN];
