#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;

// global hash
static ull B1=1000003ULL, B2=1000033ULL;
vector<ull> pw1,pw2,pf1,pf2;
void buildHash(const string&s){
    int n=s.size();
    pw1.assign(n+1,1); pw2.assign(n+1,1);
    pf1.assign(n+1,0); pf2.assign(n+1,0);
    for(int i=0;i<n;i++){
        pw1[i+1]=pw1[i]*B1; pw2[i+1]=pw2[i]*B2;
        pf1[i+1]=pf1[i]*B1 + (ull)(s[i]);
        pf2[i+1]=pf2[i]*B2 + (ull)(s[i]);
    }
}
inline ull h1(int l,int r){ return pf1[r+1]-pf1[l]*pw1[r-l+1]; }
inline ull h2(int l,int r){ return pf2[r+1]-pf2[l]*pw2[r-l+1]; }
inline bool eqSub(int a,int b,int len){ return h1(a,a+len-1)==h1(b,b+len-1) && h2(a,a+len-1)==h2(b,b+len-1); }

struct Core {
    vector<int> len,link,par,st,head,eTo,eNxt,lastNode;
    vector<char> eCh;
    int nodes;
    void build(const string&s){
        int n=s.size();
        len={-1,0}; link={0,0}; par={-1,-1}; st={-1,-1}; head={-1,-1};
        eTo.clear(); eNxt.clear(); eCh.clear();
        eTo.reserve(n+2); eNxt.reserve(n+2); eCh.reserve(n+2);
        lastNode.assign(n,0);
        nodes=2; int last=1;
        for(int pos=0;pos<n;pos++){
            int c=s[pos]-'a';
            int cur=last;
            while(true){ int cl=len[cur]; if(pos-1-cl>=0 && s[pos-1-cl]==s[pos]) break; cur=link[cur]; }
            // find transition cur,c
            int nxt=-1;
            for(int e=head[cur]; e!=-1; e=eNxt[e]) if(eCh[e]==c){ nxt=eTo[e]; break; }
            if(nxt!=-1){ last=nxt; lastNode[pos]=last; continue; }
            int v=nodes++;
            len.push_back(len[cur]+2); st.push_back(pos-len[v]+1); par.push_back(cur); head.push_back(-1);
            // add edge cur,c,v
            eCh.push_back((char)c); eTo.push_back(v); eNxt.push_back(head[cur]); head[cur]=(int)eCh.size()-1;
            if(len[v]==1) link.push_back(1);
            else{
                int t=link[cur];
                while(true){ int tl=len[t]; if(pos-1-tl>=0 && s[pos-1-tl]==s[pos]) break; t=link[t]; }
                int suf=-1;
                for(int e=head[t]; e!=-1; e=eNxt[e]) if(eCh[e]==c){ suf=eTo[e]; break; }
                link.push_back(suf);
            }
            last=v; lastNode[pos]=last;
        }
    }
};

int cmpNode(const Core&C,int a,int b,const string&s){
    int la=C.len[a], lb=C.len[b]; int a0=C.st[a], b0=C.st[b];
    int mn=min(la,lb);
    int lo=0,hi=mn;
    while(lo<hi){ int mid=(lo+hi+1)/2; if(eqSub(a0,b0,mid)) lo=mid; else hi=mid-1; }
    int x=lo;
    if(x==mn) return la<lb?-1:(la>lb?1:0);
    return s[a0+x]<s[b0+x]?-1:1;
}

vector<int> solve(const string&s){
    int n=s.size();
    buildHash(s);
    Core C; C.build(s);
    int cnt=C.nodes;
    vector<int> best(cnt);
    vector<int> ord;
    ord.reserve(cnt-2);
    for(int i=2;i<cnt;i++) ord.push_back(i);
    sort(ord.begin(),ord.end(),[&](int a,int b){ return C.len[a]<C.len[b]; });
    for(int v:ord){
        int p=C.par[v];
        if(p<=1) best[v]=v;
        else best[v]=(cmpNode(C,v,best[p],s)<0)?v:best[p];
    }
    // manacher odd
    vector<int> d1(n);
    for(int i=0,l=0,r=-1;i<n;i++){
        int k=(i>r)?1:min(d1[l+r-i],r-i+1);
        while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++;
        d1[i]=k-1;
        if(i+k-1>r){l=i-k+1;r=i+k-1;}
    }
    // mapping (len,hash) -> node
    vector<int> ids;
    ids.reserve(cnt-2);
    for(int i=2;i<cnt;i++) ids.push_back(i);
    sort(ids.begin(),ids.end(),[&](int a,int b){
        if(C.len[a]!=C.len[b]) return C.len[a]<C.len[b];
        ull ha1=h1(C.st[a],C.st[a]+C.len[a]-1), hb1=h1(C.st[b],C.st[b]+C.len[b]-1);
        if(ha1!=hb1) return ha1<hb1;
        return h2(C.st[a],C.st[a]+C.len[a]-1) < h2(C.st[b],C.st[b]+C.len[b]-1);
    });
    vector<int> ans(n);
    for(int i=0;i<n;i++){
        int R=d1[i]; int L=2*R+1; int a=i-R;
        ull q1=h1(a,a+L-1), q2=h2(a,a+L-1);
        int lo=0,hi=(int)ids.size()-1,found=-1;
        while(lo<=hi){
            int mid=(lo+hi)/2; int v=ids[mid];
            if(C.len[v]<L) lo=mid+1;
            else if(C.len[v]>L) hi=mid-1;
            else{
                ull v1=h1(C.st[v],C.st[v]+C.len[v]-1), v2=h2(C.st[v],C.st[v]+C.len[v]-1);
                if(v1<q1||(v1==q1&&v2<q2)) lo=mid+1;
                else if(v1>q1||(v1==q1&&v2>q2)) hi=mid-1;
                else { found=v; break; }
            }
        }
        if(found<0){ // should not happen
            ans[i]=-999999; continue;
        }
        ans[i]=(C.len[best[found]]-1)/2;
    }
    return ans;
}

int main(){
    mt19937 rng(2024);
    for(int iter=0;iter<30000;iter++){
        int n=1+rng()%14;
        string s(n,'a'); for(char&c:s)c='a'+rng()%3;
        vector<int> brute(n);
        for(int i=0;i<n;i++){
            int R=0; while(i-R-1>=0&&i+R+1<n&&s[i-R-1]==s[i+R+1])R++;
            int best=0; string bs=s.substr(i,1);
            for(int r=1;r<=R;r++){string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;best=r;}}
            brute[i]=best;
        }
        vector<int> got=solve(s);
        if(got!=brute){ cout<<"MISMATCH s="<<s<<"\n"; return 0; }
    }
    cout<<"ALL OK\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;

struct FastIn {
    static const int S = 1 << 20;
    char buf[S]; int idx, size;
    FastIn(): idx(0), size(0) {}
    inline char getc_() {
        if (idx >= size) { size = (int)fread(buf, 1, S, stdin); idx = 0; if (size <= 0) return 0; }
        return buf[idx++];
    }
    bool readInt(int &out) {
        char c; int sign = 1, num = 0;
        c = getc_(); if (!c) return false;
        while (c != '-' && (c < '0' || c > '9')) { c = getc_(); if (!c) return false; }
        if (c == '-') { sign = -1; c = getc_(); }
        for (; c >= '0' && c <= '9'; c = getc_()) num = num * 10 + (c - '0');
        out = num * sign; return true;
    }
    string readString() {
        string s; char c = getc_();
        while (c && (c == ' ' || c == '\n' || c == '\r' || c == '\t')) c = getc_();
        while (c && c != ' ' && c != '\n' && c != '\r' && c != '\t') { s.push_back(c); c = getc_(); }
        return s;
    }
};

static ull B1, B2;
vector<ull> pw1, pw2, pf1, pf2;

void initHash(int maxLen) {
    mt19937_64 rng((ull)chrono::steady_clock::now().time_since_epoch().count());
    B1 = (rng() | 1ULL); B2 = (rng() | 1ULL);
    if (B1 < 1000) B1 += 123456789ULL | 1ULL;
    if (B2 < 1000) B2 += 987654321ULL | 1ULL;
    if (B2 == B1) B2 += 2;
    pw1.assign(maxLen + 1, 1); pw2.assign(maxLen + 1, 1);
    pf1.assign(maxLen + 1, 0); pf2.assign(maxLen + 1, 0);
}
void buildHash(const string &s) {
    int n = (int)s.size();
    for (int i = 0; i < n; i++) {
        pw1[i+1] = pw1[i] * B1; pw2[i+1] = pw2[i] * B2;
        pf1[i+1] = pf1[i] * B1 + (ull)(unsigned char)s[i];
        pf2[i+1] = pf2[i] * B2 + (ull)(unsigned char)s[i];
    }
}
inline ull hh1(int l, int r) { return pf1[r+1] - pf1[l] * pw1[r-l+1]; }
inline ull hh2(int l, int r) { return pf2[r+1] - pf2[l] * pw2[r-l+1]; }
inline bool eqSub(int a, int b, int len) {
    return hh1(a, a+len-1) == hh1(b, b+len-1) && hh2(a, a+len-1) == hh2(b, b+len-1);
}

struct Core {
    vector<int> len, link_, par, st, head, eTo, eNxt, lastNode;
    vector<char> eCh;
    int nodes;
    void reserveAll(int maxLen) {
        int cap = maxLen + 2;
        len.reserve(cap); link_.reserve(cap); par.reserve(cap); st.reserve(cap);
        head.reserve(cap); lastNode.reserve(cap);
        eTo.reserve(cap); eNxt.reserve(cap); eCh.reserve(cap);
    }
    void build(const string &s) {
        int n = (int)s.size();
        len.clear(); link_.clear(); par.clear(); st.clear(); head.clear();
        eTo.clear(); eNxt.clear(); eCh.clear(); lastNode.clear();
        len.push_back(-1); len.push_back(0);
        link_.push_back(0); link_.push_back(0);
        par.push_back(-1); par.push_back(-1);
        st.push_back(-1); st.push_back(-1);
        head.push_back(-1); head.push_back(-1);
        lastNode.assign(n, 0);
        nodes = 2; int last = 1;
        for (int pos = 0; pos < n; pos++) {
            int c = s[pos] - 'a';
            int cur = last;
            while (true) {
                int cl = len[cur];
                if (pos - 1 - cl >= 0 && s[pos - 1 - cl] == s[pos]) break;
                cur = link_[cur];
            }
            int nxt = -1;
            for (int e = head[cur]; e != -1; e = eNxt[e]) if (eCh[e] == c) { nxt = eTo[e]; break; }
            if (nxt != -1) { last = nxt; lastNode[pos] = last; continue; }
            int v = nodes++;
            len.push_back(len[cur] + 2);
            st.push_back(pos - len[cur] - 2 + 1);
            par.push_back(cur);
            head.push_back(-1);
            eCh.push_back((char)c); eTo.push_back(v); eNxt.push_back(head[cur]); head[cur] = (int)eCh.size() - 1;
            if (len[v] == 1) link_.push_back(1);
            else {
                int t = link_[cur];
                while (true) {
                    int tl = len[t];
                    if (pos - 1 - tl >= 0 && s[pos - 1 - tl] == s[pos]) break;
                    t = link_[t];
                }
                int suf = -1;
                for (int e = head[t]; e != -1; e = eNxt[e]) if (eCh[e] == c) { suf = eTo[e]; break; }
                link_.push_back(suf);
            }
            last = v; lastNode[pos] = last;
        }
    }
};

int cmpNode(const Core &C, int a, int b, const string &s) {
    int la = C.len[a], lb = C.len[b];
    int a0 = C.st[a], b0 = C.st[b];
    int mn = min(la, lb);
    int lo = 0, hi = mn;
    while (lo < hi) {
        int mid = (lo + hi + 1) >> 1;
        if (eqSub(a0, b0, mid)) lo = mid; else hi = mid - 1;
    }
    int x = lo;
    if (x == mn) return la < lb ? -1 : (la > lb ? 1 : 0);
    return s[a0 + x] < s[b0 + x] ? -1 : 1;
}

int main() {
    FastIn in;
    int T;
    if (!in.readInt(T)) return 0;
    vector<string> tests(T);
    int maxLen = 0;
    for (int i = 0; i < T; i++) {
        tests[i] = in.readString();
        if ((int)tests[i].size() > maxLen) maxLen = (int)tests[i].size();
    }
    initHash(maxLen);
    Core C; C.reserveAll(maxLen);
    vector<int> best, d1, ord, ids;
    string out; out.reserve((size_t)maxLen * 4 + T * 2);

    auto appInt = [&](int x) {
        char tmp[12]; int k = 0;
        if (x == 0) tmp[k++] = '0';
        while (x > 0) { tmp[k++] = char('0' + x % 10); x /= 10; }
        while (k > 0) out.push_back(tmp[--k]);
    };

    for (int ti = 0; ti < T; ti++) {
        const string &s = tests[ti];
        int n = (int)s.size();
        if (n == 1) { appInt(0); out.push_back('\n'); continue; }
        buildHash(s);
        C.build(s);
        int cnt = C.nodes;
        best.assign(cnt, 0);
        ord.clear();
        for (int i = 2; i < cnt; i++) ord.push_back(i);
        sort(ord.begin(), ord.end(), [&](int a, int b) { return C.len[a] < C.len[b]; });
        for (int v : ord) {
            int p = C.par[v];
            if (p <= 1) best[v] = v;
            else best[v] = (cmpNode(C, v, best[p], s) < 0) ? v : best[p];
        }
        d1.assign(n, 0);
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i-k] == s[i+k]) k++;
            d1[i] = k - 1;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
        }
        ids.clear();
        for (int i = 2; i < cnt; i++) ids.push_back(i);
        sort(ids.begin(), ids.end(), [&](int a, int b) {
            if (C.len[a] != C.len[b]) return C.len[a] < C.len[b];
            ull a1 = hh1(C.st[a], C.st[a] + C.len[a] - 1), b1 = hh1(C.st[b], C.st[b] + C.len[b] - 1);
            if (a1 != b1) return a1 < b1;
            return hh2(C.st[a], C.st[a] + C.len[a] - 1) < hh2(C.st[b], C.st[b] + C.len[b] - 1);
        });
        for (int i = 0; i < n; i++) {
            int R = d1[i]; int L = 2 * R + 1; int a = i - R;
            ull q1 = hh1(a, a + L - 1), q2 = hh2(a, a + L - 1);
            int lo = 0, hi = (int)ids.size() - 1, found = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1; int v = ids[mid];
                if (C.len[v] < L) lo = mid + 1;
                else if (C.len[v] > L) hi = mid - 1;
                else {
                    ull v1 = hh1(C.st[v], C.st[v] + C.len[v] - 1);
                    ull v2 = hh2(C.st[v], C.st[v] + C.len[v] - 1);
                    if (v1 < q1 || (v1 == q1 && v2 < q2)) lo = mid + 1;
                    else if (v1 > q1 || (v1 == q1 && v2 > q2)) hi = mid - 1;
                    else { found = v; break; }
                }
            }
            if (found < 0) { appInt(0); }
            else appInt((C.len[best[found]] - 1) / 2);
            out.push_back(i + 1 == n ? '\n' : ' ');
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
static ull B1, B2;
vector<ull> pw1, pw2, pf1, pf2;
void initHash(int maxLen) {
    mt19937_64 rng(1234567);
    B1 = (rng() | 1ULL); B2 = (rng() | 1ULL);
    if (B1 < 1000) B1 += 123456789ULL | 1ULL;
    if (B2 < 1000) B2 += 987654321ULL | 1ULL;
    pw1.assign(maxLen + 1, 1); pw2.assign(maxLen + 1, 1);
    pf1.assign(maxLen + 1, 0); pf2.assign(maxLen + 1, 0);
}
void buildHash(const string &s) {
    int n = (int)s.size();
    for (int i = 0; i < n; i++) {
        pw1[i+1] = pw1[i] * B1; pw2[i+1] = pw2[i] * B2;
        pf1[i+1] = pf1[i] * B1 + (ull)(unsigned char)s[i];
        pf2[i+1] = pf2[i] * B2 + (ull)(unsigned char)s[i];
    }
}
inline ull hh1(int l, int r) { return pf1[r+1] - pf1[l] * pw1[r-l+1]; }
inline ull hh2(int l, int r) { return pf2[r+1] - pf2[l] * pw2[r-l+1]; }
inline bool eqSub(int a, int b, int len) {
    return hh1(a, a+len-1) == hh1(b, b+len-1) && hh2(a, a+len-1) == hh2(b, b+len-1);
}
struct Core {
    vector<int> len, link_, par, st, head, eTo, eNxt, lastNode;
    vector<char> eCh;
    int nodes;
    void reserveAll(int maxLen) {
        int cap = maxLen + 2;
        len.reserve(cap); link_.reserve(cap); par.reserve(cap); st.reserve(cap);
        head.reserve(cap); lastNode.reserve(cap);
        eTo.reserve(cap); eNxt.reserve(cap); eCh.reserve(cap);
    }
    void build(const string &s) {
        int n = (int)s.size();
        len.clear(); link_.clear(); par.clear(); st.clear(); head.clear();
        eTo.clear(); eNxt.clear(); eCh.clear(); lastNode.clear();
        len.push_back(-1); len.push_back(0);
        link_.push_back(0); link_.push_back(0);
        par.push_back(-1); par.push_back(-1);
        st.push_back(-1); st.push_back(-1);
        head.push_back(-1); head.push_back(-1);
        lastNode.assign(n, 0);
        nodes = 2; int last = 1;
        for (int pos = 0; pos < n; pos++) {
            int c = s[pos] - 'a';
            int cur = last;
            while (true) {
                int cl = len[cur];
                if (pos - 1 - cl >= 0 && s[pos - 1 - cl] == s[pos]) break;
                cur = link_[cur];
            }
            int nxt = -1;
            for (int e = head[cur]; e != -1; e = eNxt[e]) if (eCh[e] == c) { nxt = eTo[e]; break; }
            if (nxt != -1) { last = nxt; lastNode[pos] = last; continue; }
            int v = nodes++;
            len.push_back(len[cur] + 2);
            st.push_back(pos - len[cur] - 2 + 1);
            par.push_back(cur);
            head.push_back(-1);
            eCh.push_back((char)c); eTo.push_back(v); eNxt.push_back(head[cur]); head[cur] = (int)eCh.size() - 1;
            if (len[v] == 1) link_.push_back(1);
            else {
                int t = link_[cur];
                while (true) {
                    int tl = len[t];
                    if (pos - 1 - tl >= 0 && s[pos - 1 - tl] == s[pos]) break;
                    t = link_[t];
                }
                int suf = -1;
                for (int e = head[t]; e != -1; e = eNxt[e]) if (eCh[e] == c) { suf = eTo[e]; break; }
                link_.push_back(suf);
            }
            last = v; lastNode[pos] = last;
        }
    }
};
int cmpNode(const Core &C, int a, int b, const string &s) {
    int la = C.len[a], lb = C.len[b];
    int a0 = C.st[a], b0 = C.st[b];
    int mn = min(la, lb);
    int lo = 0, hi = mn;
    while (lo < hi) { int mid = (lo + hi + 1) >> 1; if (eqSub(a0, b0, mid)) lo = mid; else hi = mid - 1; }
    int x = lo;
    if (x == mn) return la < lb ? -1 : (la > lb ? 1 : 0);
    return s[a0 + x] < s[b0 + x] ? -1 : 1;
}
int main(){
    mt19937 rng(777);
    int T=20000; vector<string> tests(T); int maxLen=0;
    for(int i=0;i<T;i++){ int n=1+rng()%20; string s(n,'a'); for(char&c:s)c='a'+rng()%3; tests[i]=s; maxLen=max(maxLen,n); }
    initHash(maxLen); Core C; C.reserveAll(maxLen);
    vector<int> best,d1,ord,ids;
    for(int ti=0;ti<T;ti++){
        const string &s=tests[ti]; int n=s.size();
        if(n==1){ if(0!=0){} continue; }
        buildHash(s); C.build(s);
        int cnt=C.nodes; best.assign(cnt,0);
        ord.clear(); for(int i=2;i<cnt;i++) ord.push_back(i);
        sort(ord.begin(),ord.end(),[&](int a,int b){return C.len[a]<C.len[b];});
        for(int v:ord){ int p=C.par[v]; if(p<=1) best[v]=v; else best[v]=(cmpNode(C,v,best[p],s)<0)?v:best[p]; }
        d1.assign(n,0);
        for(int i=0,l=0,r=-1;i<n;i++){ int k=(i>r)?1:min(d1[l+r-i],r-i+1); while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++; d1[i]=k-1; if(i+k-1>r){l=i-k+1;r=i+k-1;} }
        ids.clear(); for(int i=2;i<cnt;i++) ids.push_back(i);
        sort(ids.begin(),ids.end(),[&](int a,int b){
            if(C.len[a]!=C.len[b]) return C.len[a]<C.len[b];
            ull a1=hh1(C.st[a],C.st[a]+C.len[a]-1), b1=hh1(C.st[b],C.st[b]+C.len[b]-1);
            if(a1!=b1) return a1<b1;
            return hh2(C.st[a],C.st[a]+C.len[a]-1) < hh2(C.st[b],C.st[b]+C.len[b]-1);
        });
        vector<int> got(n);
        for(int i=0;i<n;i++){
            int R=d1[i]; int L=2*R+1; int a=i-R;
            ull q1=hh1(a,a+L-1), q2=hh2(a,a+L-1);
            int lo=0,hi=(int)ids.size()-1,found=-1;
            while(lo<=hi){ int mid=(lo+hi)>>1; int v=ids[mid];
                if(C.len[v]<L) lo=mid+1; else if(C.len[v]>L) hi=mid-1;
                else { ull v1=hh1(C.st[v],C.st[v]+C.len[v]-1), v2=hh2(C.st[v],C.st[v]+C.len[v]-1);
                    if(v1<q1||(v1==q1&&v2<q2)) lo=mid+1; else if(v1>q1||(v1==q1&&v2>q2)) hi=mid-1; else {found=v;break;} } }
            got[i]=(found<0)?(-1):((C.len[best[found]]-1)/2);
        }
        // brute
        for(int i=0;i<n;i++){
            int Rr=0; while(i-Rr-1>=0&&i+Rr+1<n&&s[i-Rr-1]==s[i+Rr+1])Rr++;
            int b=0; string bs=s.substr(i,1);
            for(int r=1;r<=Rr;r++){string t=s.substr(i-r,2*r+1); if(t<bs){bs=t;b=r;}}
            if(got[i]!=b){ cout<<"MISMATCH s="<<s<<" at "<<i<<" got="<<got[i]<<" exp="<<b<<"\n"; return 0; }
        }
    }
    cout<<"ALL OK\n";
}

