void runOne(const string&s,const char*name){int n=s.size();auto t0=chrono::steady_clock::now();buildHash(s);Core C;C.reserveAll(n);C.build(s);int cnt=C.nodes;vector<int> best(cnt,0),ord,ids;d1:;vector<int> d1(n,0);ord.reserve(cnt);for(int i=2;i<cnt;i++)ord.push_back(i);sort(ord.begin(),ord.end(),[&](int a,int b){return C.len[a]<C.len[b];});for(int v:ord){int p=C.par[v];if(p<=1)best[v]=v;else best[v]=(cmpNode(C,v,best[p],s)<0)?v:best[p];}for(int i=0,l=0,r=-1;i<n;i++){int k=(i>r)?1:min(d1[l+r-i],r-i+1);while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++;d1[i]=k-1;if(i+k-1>r){l=i-k+1;r=i+k-1;}}ids.reserve(cnt);for(int i=2;i<cnt;i++)ids.push_back(i);sort(ids.begin(),ids.end(),[&](int a,int b){if(C.len[a]!=C.len[b])return C.len[a]<C.len[b];ull a1=h1(C.st[a],C.st[a]+C.len[a]-1),b1=h1(C.st[b],C.st[b]+C.len[b]-1);if(a1!=b1)return a1<b1;return h2(C.st[a],C.st[a]+C.len[a]-1)<h2(C.st[b],C.st[b]+C.len[b]-1);});long long acc=0;for(int i=0;i<n;i++){int R=d1[i],L=2*R+1,a=i-R;ull q1=h1(a,a+L-1),q2=h2(a,a+L-1);int lo=0,hi=(int)ids.size()-1,found=-1;while(lo<=hi){int mid=(lo+hi)>>1;int v=ids[mid];if(C.len[v]<L)lo=mid+1;else if(C.len[v]>L)hi=mid-1;else{ull v1=h1(C.st[v],C.st[v]+C.len[v]-1),v2=h2(C.st[v],C.st[v]+C.len[v]-1);if(v1<q1||(v1==q1&&v2<q2))lo=mid+1;else if(v1>q1||(v1==q1&&v2>q2))hi=mid-1;else{found=v;break;}}}acc+=(found<0)?0:(C.len[best[found]]-1)/2;}auto t1=chrono::steady_clock::now();cout<<name<<" nodes="<<cnt<<" time="<<chrono::duration_cast<chrono::milliseconds>(t1-t0).count()<<"ms\n";}
