        sort(ord.begin(), ord.end(), [&](int a, int b) { return C.len[a] < C.len[b]; });
        for (int v : ord) {
            int p = C.par[v];
            if (p <= 1) best[v] = v;
            else best[v] = (cmpNode(C, v, best[p], s) < 0) ? v : best[p];
        }
        d1.assign(n, 0);
        for (int i = 0, l = 0, r = -1; i < n; i++) {
            int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s[i-k] == s[i+k]) k++;
            d1[i] = k - 1;
            if (i + k - 1 > r) { l = i - k + 1; r = i + k - 1; }
        }
        ids.clear();
        for (int i = 2; i < cnt; i++) ids.push_back(i);
        sort(ids.begin(), ids.end(), [&](int a, int b) {
            if (C.len[a] != C.len[b]) return C.len[a] < C.len[b];
            ull a1 = hh1(C.st[a], C.st[a] + C.len[a] - 1), b1 = hh1(C.st[b], C.st[b] + C.len[b] - 1);
            if (a1 != b1) return a1 < b1;
            return hh2(C.st[a], C.st[a] + C.len[a] - 1) < hh2(C.st[b], C.st[b] + C.len[b] - 1);
        });
        for (int i = 0; i < n; i++) {
            int R = d1[i]; int L = 2 * R + 1; int a = i - R;
            ull q1 = hh1(a, a + L - 1), q2 = hh2(a, a + L - 1);
            int lo = 0, hi = (int)ids.size() - 1, found = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1; int v = ids[mid];
                if (C.len[v] < L) lo = mid + 1;
                else if (C.len[v] > L) hi = mid - 1;
                else {
                    ull v1 = hh1(C.st[v], C.st[v] + C.len[v] - 1);
                    ull v2 = hh2(C.st[v], C.st[v] + C.len[v] - 1);
                    if (v1 < q1 || (v1 == q1 && v2 < q2)) lo = mid + 1;
                    else if (v1 > q1 || (v1 == q1 && v2 > q2)) hi = mid - 1;
                    else { found = v; break; }
                }
            }
            if (found < 0) appInt(0);
            else appInt((C.len[best[found]] - 1) / 2);
            out.push_back(i + 1 == n ? '\n' : ' ');
        }
    }
    while (!out.empty() && (out.back() == '\n' || out.back() == ' ')) out.pop_back();
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
static const int MAXN=1000000+5;
static ull B1=0x9E3779B97F4A7C15ULL,B2=0xBF58476D1CE4E5B9ULL;
vector<ull> pw1,pw2,pf1,pf2;
void initHash(){pw1.assign(MAXN,1);pw2.assign(MAXN,1);pf1.assign(MAXN,0);pf2.assign(MAXN,0);for(int i=1;i<MAXN;i++){pw1[i]=pw1[i-1]*B1;pw2[i]=pw2[i-1]*B2;}}
void buildHash(const string&s){int n=s.size();for(int i=0;i<n;i++){pf1[i+1]=pf1[i]*B1+(ull)(unsigned char)s[i];pf2[i+1]=pf2[i]*B2+(ull)(unsigned char)s[i];}}
inline ull h1(int l,int r){return pf1[r+1]-pf1[l]*pw1[r-l+1];}
inline ull h2(int l,int r){return pf2[r+1]-pf2[l]*pw2[r-l+1];}
inline bool eq(int a,int b,int len){return h1(a,a+len-1)==h1(b,b+len-1)&&h2(a,a+len-1)==h2(b,b+len-1);}
struct Core{vector<int> len,link_,par,st,head,eTo,eNxt;vector<char> eCh;int nodes;long long cmpcalls,cmploops;
void build(const string&s){int n=s.size();len.clear();link_.clear();par.clear();st.clear();head.clear();eTo.clear();eNxt.clear();eCh.clear();len={-1,0};link_={0,0};par={-1,-1};st={-1,-1};head={-1,-1};nodes=2;int last=1;for(int pos=0;pos<n;pos++){int c=s[pos]-'a';int cur=last;while(true){int cl=len[cur];if(pos-1-cl>=0&&s[pos-1-cl]==s[pos])break;cur=link_[cur];}int nxt=-1;for(int e=head[cur];e!=-1;e=eNxt[e])if(eCh[e]==c){nxt=eTo[e];break;}if(nxt!=-1){last=nxt;continue;}int v=nodes++;len.push_back(len[cur]+2);st.push_back(pos-len[cur]-1);par.push_back(cur);head.push_back(-1);eCh.push_back((char)c);eTo.push_back(v);eNxt.push_back(head[cur]);head[cur]=(int)eCh.size()-1;if(len[v]==1)link_.push_back(1);else{int t=link_[cur];while(true){int tl=len[t];if(pos-1-tl>=0&&s[pos-1-tl]==s[pos])break;t=link_[t];}int suf=-1;for(int e=head[t];e!=-1;e=eNxt[e])if(eCh[e]==c){suf=eTo[e];break;}link_.push_back(suf);}last=v;}}};
long long cmpsteps=0;
int cmpNode(const Core&C,int a,int b,const string&s){int la=C.len[a],lb=C.len[b],a0=C.st[a],b0=C.st[b];int mn=min(la,lb);int lo=0,hi=mn;while(lo<hi){cmpsteps++;int mid=(lo+hi+1)>>1;if(eq(a0,b0,mid))lo=mid;else hi=mid-1;}int x=lo;if(x==mn)return la<lb?-1:(la>lb?1:0);return s[a0+x]<s[b0+x]?-1:1;}
double run(string s,const char*name){int n=s.size();cmpsteps=0;auto t0=chrono::steady_clock::now();
buildHash(s);Core C;C.build(s);int cnt=C.nodes;vector<int> best(cnt,0),ord;for(int i=2;i<cnt;i++)ord.push_back(i);sort(ord.begin(),ord.end(),[&](int a,int b){return C.len[a]<C.len[b];});for(int v:ord){int p=C.par[v];if(p<=1)best[v]=v;else best[v]=(cmpNode(C,v,best[p],s)<0)?v:best[p];}
vector<int> d1(n,0);for(int i=0,l=0,r=-1;i<n;i++){int k=(i>r)?1:min(d1[l+r-i],r-i+1);while(i-k>=0&&i+k<n&&s[i-k]==s[i+k])k++;d1[i]=k-1;if(i+k-1>r){l=i-k+1;r=i+k-1;}}
vector<int> ids;for(int i=2;i<cnt;i++)ids.push_back(i);sort(ids.begin(),ids.end(),[&](int a,int b){if(C.len[a]!=C.len[b])return C.len[a]<C.len[b];ull a1=h1(C.st[a],C.st[a]+C.len[a]-1),b1=h1(C.st[b],C.st[b]+C.len[b]-1);if(a1!=b1)return a1<b1;return h2(C.st[a],C.st[a]+C.len[a]-1)<h2(C.st[b],C.st[b]+C.len[b]-1);});
volatile int sink=0;for(int i=0;i<n;i++){int R=d1[i],L=2*R+1,a=i-R;ull q1=h1(a,a+L-1),q2=h2(a,a+L-1);int lo=0,hi=(int)ids.size()-1,found=-1;while(lo<=hi){int mid=(lo+hi)>>1,v=ids[mid];if(C.len[v]<L)lo=mid+1;else if(C.len[v]>L)hi=mid-1;else{ull v1=h1(C.st[v],C.st[v]+C.len[v]-1),v2=h2(C.st[v],C.st[v]+C.len[v]-1);if(v1<q1||(v1==q1&&v2<q2))lo=mid+1;else if(v1>q1||(v1==q1&&v2>q2))hi=mid-1;else{found=v;break;}}}int an=found<0?0:(C.len[best[found]]-1)/2;sink+=an;}
auto t1=chrono::steady_clock::now();double ms=chrono::duration<double,milli>(t1-t0).count();cout<<name<<" n="<<n<<" nodes="<<cnt<<" cmpsteps="<<cmpsteps<<" time="<<ms<<"ms\n";return ms;}
