#include <bits/stdc++.h>
using namespace std;
struct Core{vector<int> len,link_,par,st,head,eTo,eNxt;vector<char> eCh;int nodes;
void build(const string&s){int n=s.size();len.clear();link_.clear();par.clear();st.clear();head.clear();eTo.clear();eNxt.clear();eCh.clear();len={-1,0};link_={0,0};par={-1,-1};st={-1,-1};head={-1,-1};nodes=2;int last=1;for(int pos=0;pos<n;pos++){int c=s[pos]-'a';int cur=last;while(true){int cl=len[cur];if(pos-1-cl>=0&&s[pos-1-cl]==s[pos])break;cur=link_[cur];}int nxt=-1;for(int e=head[cur];e!=-1;e=eNxt[e])if(eCh[e]==c){nxt=eTo[e];break;}if(nxt!=-1){last=nxt;continue;}int v=nodes++;len.push_back(len[cur]+2);st.push_back(pos-len[cur]-1);par.push_back(cur);head.push_back(-1);eCh.push_back((char)c);eTo.push_back(v);eNxt.push_back(head[cur]);head[cur]=(int)eCh.size()-1;if(len[v]==1)link_.push_back(1);else{int t=link_[cur];while(true){int tl=len[t];if(pos-1-tl>=0&&s[pos-1-tl]==s[pos])break;t=link_[t];}int suf=-1;for(int e=head[t];e!=-1;e=eNxt[e])if(eCh[e]==c){suf=eTo[e];break;}link_.push_back(suf);}last=v;}}};
bool check(const string&s){int n=s.size();Core C;C.build(s);int cnt=C.nodes;
// node palindromicity and distinctness
set<string> seen;for(int v=2;v<cnt;v++){int l=C.st[v],L=C.len[v];if(l<0||l+L>n)return false;for(int j=0;j<L/2;j++)if(s[l+j]!=s[l+L-1-j]){cout<<"NONPAL s="<<s<<" v="<<v<<"\n";return false;}string t=s.substr(l,L);if(!seen.insert(t).second){cout<<"DUP s="<<s<<" v="<<v<<"\n";return false;}}
// par chain from each node should be nested and centered same
for(int v=2;v<cnt;v++){int l=C.st[v],L=C.len[v];int cen=l+(L-1)/2;int u=v;int cl=L;while(true){if(C.len[u]!=cl)return false;int ul=C.st[u],uL=C.len[u];if(ul+(uL-1)/2!=cen)return false;if(uL!=cl)return false;if(C.par[u]<=1)break;u=C.par[u];cl-=2;} }
return true;}
